    private void frameFence()throws Exception{
        CountDownLatch done=new CountDownLatch(1);
        ui(()->Choreographer.getInstance().postFrameCallback(t->Choreographer.getInstance().postFrameCallback(n->done.countDown())));
        if(!done.await(4,TimeUnit.SECONDS))throw new AssertionError("UI frame fence");
    }
