    private void tapMain(String name)throws Exception{
        View target=mainTag(name);
        ui(()->{for(android.view.ViewParent p=target.getParent();p instanceof View;p=p.getParent())if(p instanceof HorizontalScrollView)((HorizontalScrollView)p).fling(0);});
        SystemClock.sleep(80);
        ui(()->{for(android.view.ViewParent p=target.getParent();p instanceof View;p=p.getParent())if(p instanceof HorizontalScrollView){HorizontalScrollView rail=(HorizontalScrollView)p;ViewGroup content=(ViewGroup)rail.getChildAt(0);Rect area=new Rect();target.getDrawingRect(area);content.offsetDescendantRectToMyCoords(target,area);int x=rail.getScrollX();if(area.left<x)x=area.left;else if(area.right>x+rail.getWidth())x=area.right-rail.getWidth();rail.scrollTo(x,0);}});
        frameFence();
        if(!unclipped(target)){
            JSONObject debug=new JSONObject();JSONArray parents=new JSONArray();
            ui(()->{Rect r=new Rect();boolean visible=target.getGlobalVisibleRect(r);debug.put("visible",visible).put("rect",r.toShortString()).put("width",target.getWidth()).put("height",target.getHeight());for(View v=target;v!=null;v=v.getParent() instanceof View?(View)v.getParent():null){JSONObject d=new JSONObject().put("class",v.getClass().getName()).put("tag",String.valueOf(v.getTag())).put("left",v.getLeft()).put("top",v.getTop()).put("width",v.getWidth()).put("height",v.getHeight()).put("scrollX",v.getScrollX()).put("scrollY",v.getScrollY());parents.put(d);}debug.put("parents",parents);});
            Files.write(new File(output,"reach-"+name+".json").toPath(),debug.toString(2).getBytes(StandardCharsets.UTF_8));
        }
        until(()->unclipped(target),"reachable "+name);
        Rect bounds=new Rect();ui(()->target.getGlobalVisibleRect(bounds));
        long t=SystemClock.uptimeMillis();
        MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY(),0);
        down.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);down.recycle();
        SystemClock.sleep(40);
        MotionEvent up=MotionEvent.obtain(t,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY(),0);
        up.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(up,true);up.recycle();
        frameFence();
    }
    private void swipeRail(HorizontalScrollView rail)throws Exception{
        ui(()->{long t=SystemClock.uptimeMillis();for(int i=0;i<6;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==5?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent event=MotionEvent.obtain(t,t+i*40,action,rail.getWidth()*(.85f-i*.13f),rail.getHeight()/2f,0);rail.dispatchTouchEvent(event);event.recycle();}});
    }
